define("UBTConnect.controller$OnApplicationReady.SetLNCallbackJS", [], function () {
return function ($actions, $roles, $public) {
if (typeof cordova !== 'undefined' && cordova.plugins.ForegroundTrayFix) {
    cordova.plugins.ForegroundTrayFix.onNotificationClick(
        function(data) {
            if (data) {
                console.log("Notification Tapped:", data);
                var notificationObj = JSON.parse(data);
                
                // Push the callback to the end of the execution queue
                // allowing OutSystems to finish rendering the current screen
              //  setTimeout(function() { $actions.FCM_DeeplinkCallback(notificationObj);}, 0); 
                Promise.resolve().then(function() {
                    $actions.FCM_DeeplinkCallback(notificationObj);
                }).catch(function(err) {
                    console.error("Error in DeepLink Callback:", err);
                });
            }
        }, 
        function(err) {
            console.error("Plugin Listener Error:", err);
        }
    );
}
};
});
define("UBTConnect.controller$OnApplicationReady.GetCallbacksJS", [], function () {
return function ($parameters, $actions, $roles, $public) {
$parameters.FRD_CalbackFunc = $actions.FRD_UserCallback;
$parameters.OnOnline_CallbackFunc = $actions.OnOnline;
$parameters.OnOffline_CallbackFunc = $actions.OnOffiline;
$parameters.FGC_DeeplinkCallback = $actions.FCM_DeeplinkCallback;
$parameters.FGC_NotificationCallback = $actions.FCM_NotificationCallback;
};
});
define("UBTConnect.controller$OnApplicationReady.AddCustomHeadersJS", [], function () {
return function ($parameters, $actions, $roles, $public) {
(function() {
    const head = document.head || document.getElementsByTagName('head')[0];
    const urls = [$parameters.MyEntertainingURL, $parameters.FeedURL].filter(Boolean);
    const types = ['preconnect', 'dns-prefetch'];

    urls.forEach(function(url) {
        types.forEach(function(rel) {
            const link = document.createElement('link');
            link.rel = rel;
            link.href = url;
            head.appendChild(link);
        });
    });
})();
};
});
define("UBTConnect.controller$OnApplicationReady.Async_FetchCacheableMapEntitiesJS", [], function () {
return function ($actions, $roles, $public) {
$actions.Get_Cacheable_MapEntities();
$actions.Get_Cacheable_MapHouseholds();
};
});

